#include <bits/stdc++.h>
using namespace std;
int main() {
	int n;
	cin >> n;
	vector<int> a(n);
	for (int &i : a)
		cin >> i;
	set<int> s(a.begin(), a.end());
	vector<int> ans(s.begin(), s.end());
	sort(ans.begin(), ans.end());
	cout << ans.size() << endl;
